class Resp:
    def __init__(self, text):
        self.text, self.candidates = text, None


class FakeClient:
    def __init__(self, outcomes):
        self.outcomes, self.calls, self.models = list(outcomes), [], self

    def generate_content(self, model, contents, config):
        self.calls.append({"model": model, "contents": contents, "config": config})
        o = self.outcomes.pop(0) if len(self.outcomes) > 1 else self.outcomes[0]
        if isinstance(o, Exception):
            raise o
        return Resp(o)


def img(v=0, h=48, w=64):
    a = np.full((h, w, 3), v, np.uint8)
    a[: h // 2, : w // 2, 0] = 255 - v
    return a


def caller(outcomes, mode="cache_or_live", cache_dir=None):
    d = cache_dir or tempfile.mkdtemp(prefix="vlm_cache_test_")
    return GeminiCaller(LLM_CFG, mode, FakeClient(outcomes), LLMCache(d), say=lambda *_: None, sleep=lambda s: None), d


SEG = {"type": "manipulation", "description": "Grasp the beaker", "completion_criteria": "The beaker is held securely in the gripper", "primitive": "pick", "check": True, "index": 1}


def oracle(passed, reason=""):
    calls = []

    def chk(seg, ev, obs, decides=False):
        calls.append((ev, decides))
        return {"passed": passed, "reason": reason, "details": {"x": 1}}
    return {"name": "fake oracle", "check": chk, "calls": calls}


def obs(**cams):
    return {"time": 1.0, "cameras": cams}


