    class Mod:
        def __init__(self, events):
            self.n, self.events, self.started = 0, list(events), []

        def module(self):
            return {"name": "fake", "start": lambda seg: self.started.append(seg), "step": self.step, "done": lambda: self.n >= 3, "error": lambda: None, "phase": lambda: "PH",
                    "events": self.pop, "resume": lambda: None, "report": lambda: {}}

        def step(self, o):
            self.n += 1
            return {"cmd": 1}

        def pop(self):
            if self.events and self.n >= 1:
                return [self.events.pop(0)]
            return []

    def run_plan(reply, orc):
        world = WorldModel()
        world.upsert(Entry("beaker", "beaker", ("beaker",), "object", np.zeros(3), None, {"contents": "empty", "held_by": None, "height": 0.1}))
